export const article: Record<Language, PEArticle> = { en: { theme: 'Framework & Strategy', title: 'Prompt Engineering vs RAG: How to Choose', seoTitle: 'Prompt Engineering vs RAG: When to Use Each (2026)', metaDescription: 'Prompt engineering optimizes prompts; RAG adds external knowledge retrieval. Compare cost, latency, complexity, and accuracy. Decision framework and when to use each.', intro: '**Prompt engineering and RAG solve different problems.** Prompt engineering optimizes the prompt text you send to an LLM (instruction clarity, examples, format). RAG (Retrieval-Augmented Generation) augments an LLM with external knowledge retrieval before generating a response. Most teams use both: prompt engineering for general reasoning and RAG for knowledge-intensive tasks. This guide explains when to use each, their tradeoffs, and how to decide.', publishDate: '2026-04-10', dateModified: '2026-04-10', readTime: '8 min read', educationalLevel: 'Intermediate', primaryTerm: 'prompt engineering vs RAG', aboutTopics: ['prompt engineering', 'RAG', 'retrieval-augmented generation', 'knowledge retrieval', 'decision framework'], toc: [ { label: 'Key Takeaways', anchor: 'key-takeaways' }, { label: 'What is Prompt Engineering?', anchor: 'what-is-prompt-engineering' }, { label: 'What is RAG?', anchor: 'what-is-rag' }, { label: 'Side-by-Side Comparison', anchor: 'comparison' }, { label: 'Prompt Engineering: Strengths & Limits', anchor: 'prompt-engineering-strengths-limits' }, { label: 'RAG: Strengths & Limits', anchor: 'rag-strengths-limits' }, { label: 'Cost & Latency Tradeoffs', anchor: 'cost-latency' }, { label: 'Decision Framework', anchor: 'decision-framework' }, { label: 'Common Mistakes', anchor: 'common-mistakes' }, { label: 'Can You Combine Them?', anchor: 'combine' }, { label: 'Related Reading', anchor: 'related-reading' }, { label: 'FAQ', anchor: 'faq' }, { label: 'Sources', anchor: 'sources' } ], schema: { '@context': 'https://schema.org', '@type': 'TechArticle', headline: 'Prompt Engineering vs RAG: How to Choose', description: 'Prompt engineering optimizes prompts; RAG adds external knowledge retrieval. Compare cost, latency, complexity, and accuracy. Decision framework for when to use each.', datePublished: '2026-04-10', dateModified: '2026-04-10', author: { '@type': 'Person', name: 'Hans Kuepper' }, publisher: { '@type': 'Organization', name: 'PromptQuorum', url: 'https://www.promptquorum.com' }, url: 'https://www.promptquorum.com/prompt-engineering/prompt-engineering-vs-rag', inLanguage: 'en' }, faqSchema: { '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: [ { '@type': 'Question', name: 'What is prompt engineering?', acceptedAnswer: { '@type': 'Answer', text: 'Prompt engineering is optimizing the text prompt you send to an LLM to get better responses. It includes: instruction clarity, examples (few-shot), output format specification, and tone setting. It does not require external data or code changes.' } }, { '@type': 'Question', name: 'What is RAG?', acceptedAnswer: { '@type': 'Answer', text: 'RAG (Retrieval-Augmented Generation) retrieves relevant documents from an external knowledge base, then feeds them into an LLM prompt. The LLM generates a response based on both the prompt and the retrieved context.' } }, { '@type': 'Question', name: 'When should I use prompt engineering?', acceptedAnswer: { '@type': 'Answer', text: 'Use prompt engineering when the LLM already has the knowledge it needs (general reasoning, logic, creativity). Prompt engineering is fast, cheap, and requires no external infrastructure.' } }, { '@type': 'Question', name: 'When should I use RAG?', acceptedAnswer: { '@type': 'Answer', text: 'Use RAG when the LLM needs external knowledge: company documents, real-time data, domain-specific information, or proprietary datasets. RAG is essential for knowledge-intensive tasks.' } }, { '@type': 'Question', name: 'What is the cost difference?', acceptedAnswer: { '@type': 'Answer', text: 'Prompt engineering has only LLM API costs. RAG adds retrieval costs (embedding, vector DB, search) plus LLM costs (longer prompts = higher tokens). RAG typically costs 2-5x more per request.' } }, { '@type': 'Question', name: 'Which is faster?', acceptedAnswer: { '@type': 'Answer', text: 'Prompt engineering is faster (single LLM call). RAG has higher latency (retrieval lookup + embedding + LLM call). Latency difference is 500ms-2s depending on retrieval system.' } }, { '@type': 'Question', name: 'Can I use both together?', acceptedAnswer: { '@type': 'Answer', text: 'Yes. Many systems use RAG (retrieve context) + prompt engineering (optimize how context is presented to the LLM). This combines the benefits of both.' } }, { '@type': 'Question', name: 'Which is more accurate?', acceptedAnswer: { '@type': 'Answer', text: 'RAG is more accurate for knowledge-intensive tasks (retrieval prevents hallucination). Prompt engineering alone can hallucinate if the LLM lacks knowledge. For reasoning tasks, prompt engineering is sufficient.' } }, { '@type': 'Question', name: 'What happens if RAG retrieval fails?', acceptedAnswer: { '@type': 'Answer', text: 'If the knowledge base has no relevant documents, the LLM receives minimal context and may hallucinate. RAG works only as well as the knowledge base and retrieval ranking.' } }, { '@type': 'Question', name: 'Should I fine-tune instead?', acceptedAnswer: { '@type': 'Answer', text: 'Fine-tuning teaches the model new behavior (not new knowledge). For knowledge, RAG is cheaper and faster than fine-tuning. Fine-tune for style/format, use RAG for facts.' } } ] }, sections: { keyTakeaways: { isTldr: true, items: [ 'Prompt engineering: optimizes the prompt text (cheap, fast, no external data)', 'RAG: retrieves external knowledge before generating (accurate for knowledge tasks, higher cost/latency)', 'Use prompt engineering for reasoning, creativity, general knowledge tasks', 'Use RAG for knowledge-intensive tasks (documents, real-time data, proprietary info)', 'RAG + prompt engineering combined is the most powerful approach', 'RAG costs 2-5x more per request but eliminates hallucination on knowledge tasks', 'Decision: does the LLM already have the knowledge? If yes → PE. If no → RAG.' ] }, whatIsPromptEngineering: { title: 'What is Prompt Engineering?', content: '**Prompt engineering is optimizing the text prompt to get better LLM responses.** You do not change the model or add external data. You change the prompt itself: instruction clarity, examples, output format, tone, step-by-step reasoning. Examples: "Answer in JSON format" (format), "Here are 3 examples" (few-shot), "Think step-by-step" (reasoning structure). Prompt engineering works because LLMs are sensitive to phrasing — the same question phrased differently produces different quality responses.' }, whatIsRAG: { title: 'What is RAG?', content: '**RAG (Retrieval-Augmented Generation) retrieves relevant documents from an external knowledge base, then feeds them into the LLM prompt.** The LLM then generates a response based on both the prompt and the retrieved context. Example: user asks "What is our company return policy?" → RAG retrieves policy docs → LLM generates answer based on those docs. RAG solves the "hallucination on facts" problem: instead of the LLM guessing, it references a document.' }, comparison: { title: 'Side-by-Side Comparison', content: 'Here is a direct comparison:', columns: ['Aspect', 'Prompt Engineering', 'RAG'], rows: [ { 'Aspect': 'What it does', 'Prompt Engineering': 'Optimizes prompt text', 'RAG': 'Retrieves + generates' }, { 'Aspect': 'External data required', 'Prompt Engineering': 'No', 'RAG': 'Yes (knowledge base)' }, { 'Aspect': 'Cost per request', 'Prompt Engineering': '$0.001-0.01', 'RAG': '$0.005-0.05' }, { 'Aspect': 'Latency', 'Prompt Engineering': '~200ms', 'RAG': '~1-3s' }, { 'Aspect': 'Hallucination risk', 'Prompt Engineering': 'High (if LLM lacks knowledge)', 'RAG': 'Low (grounded in docs)' }, { 'Aspect': 'Infrastructure needed', 'Prompt Engineering': 'None', 'RAG': 'Vector DB, embedding model, retrieval' }, { 'Aspect': 'Best for', 'Prompt Engineering': 'Reasoning, creativity, general Q&A', 'RAG': 'Knowledge-intensive, fact-based, proprietary data' } ] }, promptEngineeringStrengths: { title: 'Prompt Engineering: Strengths & Limits', content: '**Strengths:** (1) No external infrastructure — just a prompt and an LLM. (2) Low cost — single API call, minimal tokens. (3) Fast — ~200ms end-to-end. (4) Good for reasoning — LLMs are strong at logic and creativity. (5) Flexible — can add examples, step-by-step instructions, output format on the fly.\n\n**Limits:** (1) Hallucination on facts — if the LLM does not know a fact, it invents one. (2) Knowledge cutoff — training data only goes to a certain date. (3) Limited context window — cannot reference millions of documents. (4) No personalization — cannot adapt to user-specific data without retraining.' }, ragStrengths: { title: 'RAG: Strengths & Limits', content: '**Strengths:** (1) Eliminates hallucination — responses are grounded in retrieved documents. (2) Real-time knowledge — retrieval can pull today\'s data, financial reports, emails. (3) Personalization — can retrieve user-specific documents. (4) Compliance — you control which data the model accesses. (5) Explainability — you can show which documents were cited.\n\n**Limits:** (1) Retrieval quality matters — poor retrieval → poor answers. (2) Higher cost — retrieval + embedding + longer prompts = 2-5x cost increase. (3) Higher latency — adds 500ms-2s for retrieval. (4) Infrastructure complexity — requires vector DB, embedding model, retrieval logic. (5) Still can hallucinate — if retrieved docs are incomplete or conflicting.' }, costLatency: { title: 'Cost & Latency Tradeoffs', content: '**Cost:** Prompt engineering has only LLM token costs ($0.001-0.01 per request). RAG adds: (1) Embedding API ($0.0001-0.001 per 1K tokens), (2) Vector DB storage ($0.01-0.10 per query), (3) Longer prompts (more tokens in context window). Total RAG cost: $0.005-0.05 per request (2-5x more). For 1M requests/month: PE costs $1,000-10,000. RAG costs $5,000-50,000.\n\n**Latency:** PE is ~200ms (single LLM call). RAG is ~1-3s: (1) Query embedding: 100-300ms, (2) Vector DB search: 10-100ms, (3) Document retrieval: 100-500ms, (4) LLM generation: 500-2000ms. Trade-off: RAG is slower but more accurate on knowledge tasks.' }, decisionFramework: { title: 'Decision Framework', content: '**Ask 3 questions:**\n\n**1. Does the LLM already have the knowledge?** If the task is general reasoning (math, logic, creative writing, coding), the LLM likely knows enough. Use prompt engineering.\n\nIf the task requires: company documents, real-time data, domain expertise, proprietary info — the LLM does not have it. Use RAG.\n\n**2. What is your cost/latency tolerance?** If you need <500ms response time and minimal cost (e.g., high-volume public API), use prompt engineering. If you can afford 1-3s and 2-5x cost increase, use RAG.\n\n**3. How important is accuracy on facts?** If hallucination is unacceptable (legal, financial, medical advice), use RAG. If some hallucination is tolerable (brainstorming, creative writing), use prompt engineering.\n\n**Decision tree:**\n- Knowledge task + accuracy critical? → RAG\n- General reasoning? → Prompt engineering\n- Need both? → RAG + Prompt engineering (retrieve context, then optimize how it is presented)' }, commonMistakes: { title: 'Common Mistakes', items: [ 'Using RAG for tasks where prompt engineering is enough — adds cost and latency unnecessarily. Example: asking GPT-4o "What is the capital of France?" does not need RAG.', 'Using prompt engineering for knowledge tasks — leads to hallucination. Example: asking an LLM to cite your company policies without providing them via RAG.', 'Building RAG without investing in retrieval quality — a retrieval system is only as good as its indexing and ranking. Poor retrieval → poor answers.', 'Thinking RAG eliminates hallucination entirely — RAG reduces hallucination but does not eliminate it. If retrieval finds incomplete or conflicting docs, the LLM can still make mistakes.', 'Not measuring end-to-end latency — RAG latency includes retrieval + embedding + LLM. Total latency matters for user experience, not just LLM response time.', 'Using RAG without a fallback — if retrieval fails or finds nothing, the LLM receives minimal context. Have a fallback plan (default response, re-prompt with broader search).' ] }, combine: { title: 'Can You Combine Them?', content: '**Yes — and you should.** The optimal approach for knowledge-intensive applications is: (1) RAG (retrieve relevant documents), (2) Prompt engineering (optimize how context is presented to the LLM). Example: Retrieve support docs → Prompt engineer the context format → LLM generates a helpful response. This combines RAG\'s accuracy with prompt engineering\'s clarity. Most production systems use both.' }, relatedReading: { title: 'Related Reading', items: [ '[What is Prompt Engineering? A Beginner\'s Guide](/prompt-engineering/what-is-prompt-engineering-a-beginners-guide)', '[Best Prompt Engineering Tools 2026: Ranked by Use Case](/prompt-engineering/best-prompt-engineering-tools-2026)', '[RAG Architecture: Building Retrieval-Augmented Generation Systems](/prompt-engineering/rag-architecture)', '[Fine-Tuning vs Prompt Engineering: When to Use Each](/prompt-engineering/fine-tuning-vs-prompt-engineering)', '[How to Build a Prompt Library for Teams](/prompt-engineering/build-a-prompt-library)', '[Hallucination in LLMs: Causes and Fixes](/prompt-engineering/ai-hallucinations-how-to-stop)' ] }, faq: { title: 'FAQ', faqs: [ { q: 'What is prompt engineering?', a: 'Prompt engineering is optimizing the text prompt you send to an LLM to get better responses. It includes instruction clarity, examples (few-shot), output format, and tone. It does not require external data.' }, { q: 'What is RAG?', a: 'RAG retrieves relevant documents from an external knowledge base, then feeds them to an LLM. The LLM generates a response grounded in those documents.' }, { q: 'When should I use prompt engineering?', a: 'Use it for reasoning, creativity, and general knowledge tasks where the LLM already knows enough. It is fast, cheap, and requires no infrastructure.' }, { q: 'When should I use RAG?', a: 'Use it for knowledge-intensive tasks: company documents, real-time data, domain expertise, proprietary info. Essential when hallucination is unacceptable.' }, { q: 'What is the cost difference?', a: 'Prompt engineering: $0.001-0.01 per request. RAG: $0.005-0.05 per request (2-5x higher due to retrieval, embedding, longer prompts).' }, { q: 'Which is faster?', a: 'Prompt engineering: ~200ms. RAG: ~1-3s (includes retrieval lookup, embedding, document fetch, LLM generation).' }, { q: 'Can I use both together?', a: 'Yes. Retrieve context with RAG, then use prompt engineering to optimize how that context is presented. This is the most powerful approach.' }, { q: 'Which is more accurate?', a: 'RAG is more accurate for facts (grounded in documents). Prompt engineering is sufficient for reasoning and creativity.' }, { q: 'What if RAG retrieval fails?', a: 'If the knowledge base has no relevant documents, the LLM gets minimal context and may hallucinate. RAG quality depends on retrieval quality.' }, { q: 'Should I fine-tune instead?', a: 'Fine-tuning teaches style/format changes. For knowledge, RAG is cheaper and faster. Use RAG for facts, fine-tune for behavior.' } ] }, sources: { title: 'Sources', items: [ '[Prompt Engineering Guide - OpenAI](https://platform.openai.com/docs/guides/prompt-engineering)', '[Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks](https://arxiv.org/abs/2005.11401)', '[RAG vs Fine-tuning - LangChain](https://docs.langchain.com/modules/retrieval/)', '[What is RAG? - Anthropic](https://www.anthropic.com/research)', '[Vector Databases and Semantic Search](https://www.pinecone.io/learn/)' ] } } }, de: { theme: 'Framework & Strategie', title: 'Prompt Engineering vs RAG: Wann welches nutzen', seoTitle: 'Prompt Engineering vs RAG: Wann welches nutzen (2026)', metaDescription: 'Prompt Engineering optimiert Prompts, RAG ruft externe Wissensquellen ab. Vergleich, Kosten, Komplexität und DSGVO-Compliance.', intro: '**Prompt Engineering und RAG lösen unterschiedliche Probleme.** Prompt Engineering optimiert den Prompt-Text, den Sie an ein LLM senden (Klarheit, Beispiele, Format). RAG (Retrieval-Augmented Generation) ergänzt ein LLM mit externer Wissensbeschaffung vor der Antwortgenerierung. Die meisten Teams nutzen beide: Prompt Engineering für allgemeine Aufgaben, RAG für wissensintensive Aufgaben. Dieser Leitfaden erklärt, wann Sie jeweils einsetzen, ihre Tradeoffs und wie Sie entscheiden.', publishDate: '2026-04-10', dateModified: '2026-04-10', readTime: '8 Min. Lesezeit', educationalLevel: 'Intermediate', primaryTerm: 'Prompt Engineering vs RAG', aboutTopics: ['Prompt Engineering', 'RAG', 'Retrieval-Augmented Generation', 'Wissensbeschaffung', 'Entscheidungsrahmen'], toc: [ { label: 'Zusammenfassung', anchor: 'key-takeaways' }, { label: 'Was ist Prompt Engineering?', anchor: 'what-is-prompt-engineering' }, { label: 'Was ist RAG?', anchor: 'what-is-rag' }, { label: 'Nebeneinander-Vergleich', anchor: 'comparison' }, { label: 'Prompt Engineering: Stärken & Schwächen', anchor: 'prompt-engineering-strengths-limits' }, { label: 'RAG: Stärken & Schwächen', anchor: 'rag-strengths-limits' }, { label: 'Kosten & Latenz-Tradeoffs', anchor: 'cost-latency' }, { label: 'Entscheidungsrahmen', anchor: 'decision-framework' }, { label: 'Häufige Fehler', anchor: 'common-mistakes' }, { label: 'Können Sie diese kombinieren?', anchor: 'combine' }, { label: 'Weiterführende Ressourcen', anchor: 'related-reading' }, { label: 'FAQ', anchor: 'faq' }, { label: 'Quellen', anchor: 'sources' } ], schema: { '@context': 'https://schema.org', '@type': 'TechArticle', headline: 'Prompt Engineering vs RAG: Wann welches nutzen', description: 'Prompt Engineering optimiert Prompts, RAG ruft externe Wissensbeschaffung ab. Vergleich, Kosten, Komplexität und DSGVO-Compliance.', datePublished: '2026-04-10', dateModified: '2026-04-10', author: { '@type': 'Person', name: 'Hans Kuepper' }, publisher: { '@type': 'Organization', name: 'PromptQuorum', url: 'https://www.promptquorum.com' }, url: 'https://www.promptquorum.com/prompt-engineering/prompt-engineering-vs-rag?lang=de', inLanguage: 'de' }, faqSchema: { '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: [ { '@type': 'Question', name: 'Was ist Prompt Engineering?', acceptedAnswer: { '@type': 'Answer', text: 'Prompt Engineering ist die Optimierung des Textes, den Sie an ein LLM senden, um bessere Antworten zu erhalten. Dazu gehören: Anweisungsklarheit, Beispiele (Few-Shot), Ausgabeformatspezifikation und Ton. Es erfordert keine externen Daten oder Codeänderungen.' } }, { '@type': 'Question', name: 'Was ist RAG?', acceptedAnswer: { '@type': 'Answer', text: 'RAG (Retrieval-Augmented Generation) ruft relevante Dokumente aus einer externen Wissensdatenbank ab und füttert sie in einen LLM-Prompt. Das LLM generiert dann eine Antwort basierend auf dem Prompt und dem abgerufenen Kontext.' } }, { '@type': 'Question', name: 'Wann sollte ich Prompt Engineering nutzen?', acceptedAnswer: { '@type': 'Answer', text: 'Nutzen Sie es für Aufgaben, bei denen das LLM bereits das notwendige Wissen hat (Logik, Kreativität, allgemeines Reasoning). Prompt Engineering ist schnell, kostengünstig und erfordert keine externe Infrastruktur.' } }, { '@type': 'Question', name: 'Wann sollte ich RAG nutzen?', acceptedAnswer: { '@type': 'Answer', text: 'Nutzen Sie RAG, wenn das LLM externes Wissen benötigt: Unternehmensdokumente, Echtzeit-Daten, Domänenwissen oder proprietäre Datensätze. RAG ist essentiell für wissensintensive Aufgaben.' } }, { '@type': 'Question', name: 'Was ist der Kostenunterschied?', acceptedAnswer: { '@type': 'Answer', text: 'Prompt Engineering: nur LLM API-Kosten ($0,001–0,01 pro Anfrage). RAG fügt hinzu: Abrufkosten (Embedding, Vector DB, Suche) plus LLM-Kosten (längere Prompts = höhere Tokens). RAG kostet typisch 2–5x mehr pro Anfrage.' } }, { '@type': 'Question', name: 'Welches ist schneller?', acceptedAnswer: { '@type': 'Answer', text: 'Prompt Engineering ist schneller (~200ms für einen LLM-Aufruf). RAG hat höhere Latenz (~1–3s): Abruf-Lookup + Embedding + LLM-Aufruf. Latenz-Unterschied ist 500ms–2s je nach Abrufsystem.' } }, { '@type': 'Question', name: 'Kann ich beide zusammen nutzen?', acceptedAnswer: { '@type': 'Answer', text: 'Ja. Viele Systeme nutzen RAG (Kontext abrufen) + Prompt Engineering (optimieren, wie der Kontext dem LLM präsentiert wird). Das kombiniert die Vorteile beider.' } }, { '@type': 'Question', name: 'Welches ist genauer?', acceptedAnswer: { '@type': 'Answer', text: 'RAG ist genauer für wissensintensive Aufgaben (Abruf verhindert Halluzinationen). Prompt Engineering allein kann halluzinieren, wenn dem LLM Wissen fehlt. Für Reasoning-Aufgaben reicht Prompt Engineering aus.' } }, { '@type': 'Question', name: 'Was passiert, wenn der RAG-Abruf fehlschlägt?', acceptedAnswer: { '@type': 'Answer', text: 'Wenn die Wissensdatenbank keine relevanten Dokumente hat, erhält das LLM minimalen Kontext und kann halluzinieren. RAG funktioniert nur so gut wie die Wissensdatenbank und das Abruf-Ranking.' } }, { '@type': 'Question', name: 'Sollte ich statt dessen Fine-Tuning nutzen?', acceptedAnswer: { '@type': 'Answer', text: 'Fine-Tuning lehrt dem Modell neues Verhalten (nicht neues Wissen). Für Wissen ist RAG billiger und schneller als Fine-Tuning. Fine-Tune für Stil/Format, nutzen Sie RAG für Fakten.' } }, { '@type': 'Question', name: 'Was ist die DSGVO-Compliance für RAG?', acceptedAnswer: { '@type': 'Answer', text: 'RAG-Systeme müssen DSGVO Art. 28 (Auftragsverarbeitung) einhalten. Der Verantwortliche (Sie) kontrolliert, welche Daten in die Wissensdatenbank aufgenommen werden. Lokale RAG-Systeme (on-premise) erfüllen Datenspeicherungspflichten. Verifizieren Sie den Datenfluss und die Verarbeitung mit Ihrem RAG-Anbieter.' } } ] }, sections: { keyTakeaways: { isTldr: true, items: [ 'Prompt Engineering: optimiert Prompt-Text (kostengünstig, schnell, keine externen Daten)', 'RAG: ruft externes Wissen ab, bevor es antwortet (genau für Wissen, höhere Kosten/Latenz)', 'Nutzen Sie Prompt Engineering für Reasoning, Kreativität, allgemeines Wissen', 'Nutzen Sie RAG für wissensintensive Aufgaben (Dokumente, Echtzeit-Daten, Proprietäres)', 'RAG + Prompt Engineering kombiniert ist der mächtigste Ansatz', 'RAG kostet 2–5x mehr pro Anfrage, aber eliminiert Halluzinationen bei Wissensfragen', 'Entscheidung: Hat das LLM das Wissen bereits? Ja → PE. Nein → RAG.' ] }, whatIsPromptEngineering: { title: 'Was ist Prompt Engineering?', content: '**Prompt Engineering ist die Optimierung des Textes, um bessere LLM-Antworten zu erhalten.** Sie ändern nicht das Modell oder fügen externe Daten hinzu. Sie ändern den Prompt selbst: Anweisungsklarheit, Beispiele, Ausgabeformat, Ton, Schritt-für-Schritt-Reasoning. Beispiele: „Antworte im JSON-Format" (Format), „Hier sind 3 Beispiele" (Few-Shot), „Denke Schritt für Schritt" (Reasoning-Struktur). Prompt Engineering funktioniert, weil LLMs auf Phrasing sensibel sind – die gleiche Frage unterschiedlich phrasing erzeugt unterschiedliche Qualität.' }, whatIsRAG: { title: 'Was ist RAG?', content: '**RAG (Retrieval-Augmented Generation) ruft relevante Dokumente aus einer externen Wissensdatenbank ab und füttert sie in den LLM-Prompt.** Das LLM generiert dann eine Antwort basierend auf Prompt und abgerufenem Kontext. Beispiel: Benutzer fragt „Was ist unsere Rückgaberichtlinie?" → RAG ruft Policy-Dokumente ab → LLM generiert Antwort basierend auf diesen Dokumenten. RAG löst das „Halluzinationsproblem bei Fakten": statt zu raten, referenziert das LLM ein Dokument.' }, comparison: { title: 'Nebeneinander-Vergleich', content: 'Hier ist ein direkter Vergleich:', columns: ['Aspekt', 'Prompt Engineering', 'RAG'], rows: [ { 'Aspekt': 'Was es tut', 'Prompt Engineering': 'Optimiert Prompt-Text', 'RAG': 'Ruft ab + generiert' }, { 'Aspekt': 'Externe Daten erforderlich', 'Prompt Engineering': 'Nein', 'RAG': 'Ja (Wissensdatenbank)' }, { 'Aspekt': 'Kosten pro Anfrage', 'Prompt Engineering': '$0,001–0,01', 'RAG': '$0,005–0,05' }, { 'Aspekt': 'Latenz', 'Prompt Engineering': '~200ms', 'RAG': '~1–3s' }, { 'Aspekt': 'Halluzinationsrisiko', 'Prompt Engineering': 'Hoch (wenn LLM Wissen fehlt)', 'RAG': 'Niedrig (verankert in Docs)' }, { 'Aspekt': 'Erforderliche Infrastruktur', 'Prompt Engineering': 'Keine', 'RAG': 'Vector DB, Embedding-Modell, Abruf' }, { 'Aspekt': 'Beste für', 'Prompt Engineering': 'Reasoning, Kreativität, allgemeine Fragen', 'RAG': 'Wissensintensiv, faktengestützt, Proprietäres' } ] }, promptEngineeringStrengths: { title: 'Prompt Engineering: Stärken & Schwächen', content: '**Stärken:** (1) Keine externe Infrastruktur – nur Prompt und LLM. (2) Niedrige Kosten – einzelner API-Aufruf, minimale Tokens. (3) Schnell – ~200ms von Ende zu Ende. (4) Gut für Reasoning – LLMs sind stark in Logik und Kreativität. (5) Flexibel – kann Beispiele, Schritt-für-Schritt-Anweisungen, Ausgabeformat spontan hinzufügen.\n\n**Schwächen:** (1) Halluzination bei Fakten – wenn LLM einen Fakt nicht kennt, erfindet es einen. (2) Knowledge Cutoff – Trainingsdaten gehen nur bis zu einem bestimmten Datum. (3) Begrenzte Kontextfenster – kann nicht Millionen von Dokumenten referenzieren. (4) Keine Personalisierung – kann nicht ohne Umtraining an benutzerspezifische Daten anpassen.' }, ragStrengths: { title: 'RAG: Stärken & Schwächen', content: '**Stärken:** (1) Eliminiert Halluzination – Antworten sind in abgerufenen Dokumenten verankert. (2) Echtzeit-Wissen – Abruf kann aktuelle Daten, Finanzberichte, E-Mails abrufen. (3) Personalisierung – kann benutzerspezifische Dokumente abrufen. (4) Compliance – Sie kontrollieren, welche Daten das Modell zugreift. (5) Nachvollziehbarkeit – Sie können zeigen, welche Dokumente zitiert wurden.\n\n**Schwächen:** (1) Abrufqualität zählt – schlechter Abruf → schlechte Antworten. (2) Höhere Kosten – Abruf + Embedding + längere Prompts = 2–5x Kostenerhöhung. (3) Höhere Latenz – fügt 500ms–2s für Abruf hinzu. (4) Infrastruktur-Komplexität – erfordert Vector DB, Embedding-Modell, Abruf-Logik. (5) Kann immer noch halluzinieren – wenn abgerufene Dokumente unvollständig oder widersprüchlich sind.' }, costLatency: { title: 'Kosten & Latenz-Tradeoffs', content: '**Kosten:** Prompt Engineering hat nur LLM-Token-Kosten ($0,001–0,01 pro Anfrage). RAG fügt hinzu: (1) Embedding API ($0,0001–0,001 pro 1K Tokens), (2) Vector DB Speicherung ($0,01–0,10 pro Abfrage), (3) Längere Prompts (mehr Tokens im Kontextfenster). Gesamt-RAG-Kosten: $0,005–0,05 pro Anfrage (2–5x mehr). Für 1M Anfragen/Monat: PE kostet $1.000–10.000. RAG kostet $5.000–50.000.\n\n**Latenz:** PE ist ~200ms (einzelner LLM-Aufruf). RAG ist ~1–3s: (1) Abfrage-Embedding: 100–300ms, (2) Vector DB Suche: 10–100ms, (3) Dokument-Abruf: 100–500ms, (4) LLM-Generierung: 500–2000ms. Tradeoff: RAG ist langsamer, aber genauer bei Wissensfragen.' }, decisionFramework: { title: 'Entscheidungsrahmen', content: '**Fragen Sie 3 Fragen:**\n\n**1. Hat das LLM das Wissen bereits?** Wenn die Aufgabe allgemeines Reasoning ist (Mathe, Logik, kreatives Schreiben, Programmierung), kennt das LLM wahrscheinlich genug. Nutzen Sie Prompt Engineering.\n\nWenn die Aufgabe erfordert: Unternehmensdokumente, Echtzeit-Daten, Domänenwissen, Proprietäres – hat das LLM es nicht. Nutzen Sie RAG.\n\n**2. Wie ist Ihre Kosten-/Latenz-Toleranz?** Wenn Sie <500ms brauchen und minimale Kosten (z. B. hochvolumiges Public API), nutzen Sie Prompt Engineering. Wenn Sie 1–3s und 2–5x Kostenerhöhung tolerieren können, nutzen Sie RAG.\n\n**3. Wie wichtig ist Genauigkeit bei Fakten?** Wenn Halluzination inakzeptabel ist (rechtlich, finanziell, medizinisch), nutzen Sie RAG. Wenn etwas Halluzination tolerierbar ist (Brainstorming, kreatives Schreiben), nutzen Sie Prompt Engineering.\n\n**Entscheidungsbaum:**\n- Wissensfrage + Genauigkeit kritisch? → RAG\n- Allgemeines Reasoning? → Prompt Engineering\n- Beide brauchen? → RAG + Prompt Engineering (Kontext abrufen, dann optimieren, wie es präsentiert wird)' }, commonMistakes: { title: 'Häufige Fehler', items: [ 'RAG für Aufgaben nutzen, wo Prompt Engineering reicht – fügt unnötige Kosten und Latenz hinzu. Beispiel: „Was ist die Hauptstadt von Frankreich?" zu GPT-4o fragen braucht nicht RAG.', 'Prompt Engineering für Wissensfragen nutzen – führt zu Halluzination. Beispiel: ein LLM fragen, Ihre Unternehmensrichtlinien zu zitieren, ohne sie via RAG bereitzustellen.', 'RAG bauen ohne in Abrufqualität zu investieren – ein Abrufsystem ist nur so gut wie sein Indexieren und Ranking. Schlechter Abruf → schlechte Antworten.', 'Denken, RAG eliminiert Halluzination völlig – RAG reduziert Halluzination, eliminiert sie aber nicht. Wenn Abruf unvollständige oder widersprüchliche Dokumente findet, kann das LLM immer noch Fehler machen.', 'Nicht End-zu-End-Latenz messen – RAG-Latenz inkludiert Abruf + Embedding + LLM. Gesamt-Latenz zählt für UX, nicht nur LLM-Antwortzeit.', 'RAG ohne Fallback nutzen – wenn Abruf fehlschlägt oder nichts findet, erhält LLM minimalen Kontext. Haben Sie einen Fallback-Plan (Standardantwort, mit breiterer Suche erneut fragen).' ] }, combine: { title: 'Können Sie diese kombinieren?', content: '**Ja – und Sie sollten.** Der optimale Ansatz für wissensintensive Anwendungen ist: (1) RAG (relevante Dokumente abrufen), (2) Prompt Engineering (optimieren, wie Kontext dem LLM präsentiert wird). Beispiel: Support-Docs abrufen → Prompt Engineering des Kontext-Formats → LLM generiert hilfreiche Antwort. Das kombiniert RAGs Genauigkeit mit Prompt Engineerings Klarheit. Die meisten Produktionssysteme nutzen beide.' }, relatedReading: { title: 'Weiterführende Ressourcen', items: [ '[Was ist Prompt Engineering? Ein Anfängerleitfaden](/prompt-engineering/what-is-prompt-engineering-a-beginners-guide?lang=de)', '[Die besten Prompt Engineering Tools 2026: Nach Use Case bewertet](/prompt-engineering/best-prompt-engineering-tools-2026?lang=de)', '[RAG-Architektur: Aufbau von Retrieval-Augmented Generation Systemen](/prompt-engineering/rag-architecture?lang=de)', '[Fine-Tuning vs Prompt Engineering: Wann welches nutzen](/prompt-engineering/fine-tuning-vs-prompt-engineering?lang=de)', '[Wie man eine Prompt-Bibliothek für Teams aufbaut](/prompt-engineering/build-a-prompt-library?lang=de)', '[Halluzination in LLMs: Ursachen und Lösungen](/prompt-engineering/ai-hallucinations-how-to-stop?lang=de)' ] }, faq: { title: 'FAQ', faqs: [ { q: 'Was ist Prompt Engineering?', a: 'Prompt Engineering ist die Optimierung des Textes, den Sie an ein LLM senden. Dazu gehören Anweisungen, Beispiele, Ausgabeformat. Keine externen Daten erforderlich.' }, { q: 'Was ist RAG?', a: 'RAG ruft relevante Dokumente aus einer Wissensdatenbank ab, füttert sie dann das LLM. Das LLM generiert eine Antwort, die in diesen Dokumenten verankert ist.' }, { q: 'Wann sollte ich Prompt Engineering nutzen?', a: 'Für Reasoning, Kreativität und allgemeines Wissen, das das LLM bereits hat. Schnell, kostengünstig, keine Infrastruktur.' }, { q: 'Wann sollte ich RAG nutzen?', a: 'Für wissensintensive Aufgaben: Unternehmensdokumente, Echtzeit-Daten, Domänenwissen. Essentiell, wenn Halluzination inakzeptabel ist.' }, { q: 'Was ist der Kostenunterschied?', a: 'PE: $0,001–0,01 pro Anfrage. RAG: $0,005–0,05 pro Anfrage (2–5x höher wegen Abruf, Embedding, längere Prompts).' }, { q: 'Welches ist schneller?', a: 'PE: ~200ms. RAG: ~1–3s (Abruf-Lookup, Embedding, Dokument-Abruf, LLM-Generierung).' }, { q: 'Kann ich beide zusammen nutzen?', a: 'Ja. Kontext mit RAG abrufen, dann Prompt Engineering nutzen, um zu optimieren, wie dieser Kontext präsentiert wird. Mächtigster Ansatz.' }, { q: 'Welches ist genauer?', a: 'RAG genauer für Fakten (verankert in Dokumenten). PE reicht für Reasoning und Kreativität.' }, { q: 'Was, wenn RAG-Abruf fehlschlägt?', a: 'Wenn Wissensdatenbank keine relevanten Dokumente hat, bekommt LLM minimalen Kontext und kann halluzinieren. RAG-Qualität hängt von Abruf-Qualität ab.' }, { q: 'Sollte ich Fine-Tuning statt dessen nutzen?', a: 'Fine-Tuning lehrt Stil-/Format-Änderungen. Für Wissen ist RAG billiger und schneller. RAG für Fakten, Fine-Tune für Verhalten.' }, { q: 'Was ist die DSGVO-Compliance für RAG?', a: 'RAG muss DSGVO Art. 28 einhalten. Sie kontrollieren, welche Daten in die Wissensdatenbank gehen. Lokale RAG erfüllt Datenspeicher-Pflichten. Verifizieren Sie Datenfluss mit Ihrem Anbieter.' } ] }, sources: { title: 'Quellen', items: [ '[Prompt Engineering Leitfaden - OpenAI](https://platform.openai.com/docs/guides/prompt-engineering)', '[Retrieval-Augmented Generation für Knowledge-Intensive NLP-Aufgaben](https://arxiv.org/abs/2005.11401)', '[RAG vs Fine-tuning - LangChain](https://docs.langchain.com/modules/retrieval/)', '[Was ist RAG? - Anthropic](https://www.anthropic.com/research)', '[Vector Datenbanken und semantische Suche](https://www.pinecone.io/learn/)' ] } } }, fr: { theme: 'Tools & Platforms', title: 'RAG', seoTitle: 'RAG', metaDescription: 'RAG', intro: '[Translation coming soon](/prompt-engineering/best-prompt-engineering-tools-2026?lang=en).', publishDate: '2026-04-10', readTime: '8 min', educationalLevel: 'Intermediate', sections: {} }, ja: { theme: 'Tools & Platforms', title: 'RAG', seoTitle: 'RAG', metaDescription: 'RAG', intro: '[Translation coming soon](/prompt-engineering/best-prompt-engineering-tools-2026?lang=en).', publishDate: '2026-04-10', readTime: '8 min', educationalLevel: 'Intermediate', sections: {} }, zh: { freshness_tier: 'semi_annual', theme: 'Tools & Platforms', title: 'RAG', seoTitle: 'RAG', metaDescription: 'RAG', intro: '[Translation coming soon](/prompt-engineering/best-prompt-engineering-tools-2026?lang=en).', publishDate: '2026-04-10', readTime: '8 min', educationalLevel: 'Intermediate', sections: {} } };
